        }
        for (int i = 0; i < n; i++) {
            y[i] = sc.nextLong();
        }

        if (n <= 2) {
            System.out.println(0);
            return;
        }

        u = new long[n];
        v = new long[n];

        minU = Long.MAX_VALUE;
        maxU = Long.MIN_VALUE;
        minV = Long.MAX_VALUE;
        maxV = Long.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            u[i] = x[i] + y[i];
            v[i] = x[i] - y[i];
            if (u[i] < minU) minU = u[i];
            if (u[i] > maxU) maxU = u[i];
            if (v[i] < minV) minV = v[i];
            if (v[i] > maxV) maxV = v[i];
        }

        long low = 0;
        long high = Math.max(maxU - minU, maxV - minV);
        long ans = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(ans);
    }
}
